/**
 * amfa-442 #5/#6: validateAdminOperation must scope SPA_<org> to its own org
 * (own SPA group + TA groups of the org's tenants) and TA_* to targets whose
 * whole role set lies inside the requester's TA groups. Tenant t1 belongs to
 * orgA, t2 to orgB.
 */
import { test, describe, mock } from "node:test";
import assert from "node:assert/strict";
import * as ddb from "@aws-sdk/client-dynamodb";
import { AdminListGroupsForUserCommand } from "@aws-sdk/client-cognito-identity-provider";

process.env.USERPOOL_ID = "us-east-1_ADMINPOOL";
process.env.AMFATENANT_TABLE = "amfa-tenanttable";

// Tenant table GSI org-id-index: orgA -> t1, orgB -> t2.
const tenantsByOrg = { orgA: ["t1"], orgB: ["t2"] };
mock.method(ddb.DynamoDBClient.prototype, "send", async (cmd) => {
  assert.ok(cmd instanceof ddb.QueryCommand);
  assert.equal(cmd.input.IndexName, "org-id-index");
  const orgId = cmd.input.ExpressionAttributeValues[":orgId"].S;
  return {
    Items: (tenantsByOrg[orgId] || []).map((t) => ({ id: { S: `TENANT#${t}` }, org_id: { S: orgId } })),
  };
});

const { validateAdminOperation } = await import("../admin-utils.mjs");

// Target users keyed by username -> their Cognito groups.
const targets = {
  "sa@example.com": ["SA"],
  "spa-a@example.com": ["SPA_orgA"],
  "spa-b@example.com": ["SPA_orgB"],
  "ta-1@example.com": ["TA_t1"],
  "ta-2@example.com": ["TA_t2"],
  "ta-12@example.com": ["TA_t1", "TA_t2"],
  "spa-a-ta-1@example.com": ["SPA_orgA", "TA_t1"],
  "spa-a-ta-2@example.com": ["SPA_orgA", "TA_t2"],
  "none@example.com": [],
};
const cognito = {
  async send(cmd) {
    assert.ok(cmd instanceof AdminListGroupsForUserCommand);
    const groups = targets[cmd.input.Username];
    if (!groups) throw Object.assign(new Error("User does not exist."), { name: "UserNotFoundException" });
    return { Groups: groups.map((g) => ({ GroupName: g })) };
  },
};

const realLog = console.log;
console.log = () => {};
test.after(() => { console.log = realLog; });

// requester roles (as prioritizeRoles returns them) -> target -> allowed?
const matrix = {
  "SA": {
    "sa@example.com": true, "spa-a@example.com": true, "spa-b@example.com": true,
    "ta-1@example.com": true, "ta-2@example.com": true, "ta-12@example.com": true,
  },
  "SPA_orgA": {
    "sa@example.com": false, "spa-a@example.com": true, "spa-b@example.com": false,
    "ta-1@example.com": true, "ta-2@example.com": false, "ta-12@example.com": false,
    "spa-a-ta-1@example.com": true, "spa-a-ta-2@example.com": false, "none@example.com": false,
  },
  "SPA_orgB": {
    "sa@example.com": false, "spa-a@example.com": false, "spa-b@example.com": true,
    "ta-1@example.com": false, "ta-2@example.com": true, "ta-12@example.com": false,
    "spa-a-ta-1@example.com": false, "none@example.com": false,
  },
  "TA_t1": {
    "sa@example.com": false, "spa-a@example.com": false, "spa-b@example.com": false,
    "ta-1@example.com": true, "ta-2@example.com": false, "ta-12@example.com": false,
    "spa-a-ta-1@example.com": false, "none@example.com": false,
  },
  "TA_t2": {
    "sa@example.com": false, "spa-a@example.com": false, "spa-b@example.com": false,
    "ta-1@example.com": false, "ta-2@example.com": true, "ta-12@example.com": false,
  },
  "TA_t1,TA_t2": {
    "ta-1@example.com": true, "ta-2@example.com": true, "ta-12@example.com": true,
    "spa-a@example.com": false, "spa-a-ta-1@example.com": false,
  },
};

describe("validateAdminOperation (amfa-442 #5/#6)", () => {
  for (const [requester, row] of Object.entries(matrix)) {
    const roles = requester.split(",");
    for (const [target, allowed] of Object.entries(row)) {
      for (const op of ["GET", "PUT", "DELETE"]) {
        test(`${requester} ${op} ${target} [${targets[target].join(",")}] -> ${allowed ? "allowed" : "denied"}`, async () => {
          const r = await validateAdminOperation(roles, op, target, cognito);
          assert.equal(r.isValid, allowed, r.error);
          if (!allowed) assert.equal(typeof r.error, "string");
        });
      }
    }
  }

  test("unknown target user -> denied for SPA and TA (fail closed)", async () => {
    assert.equal((await validateAdminOperation(["SPA_orgA"], "GET", "ghost@example.com", cognito)).isValid, false);
    assert.equal((await validateAdminOperation(["TA_t1"], "GET", "ghost@example.com", cognito)).isValid, false);
  });

  test("no requester roles or no target -> denied", async () => {
    assert.equal((await validateAdminOperation([], "GET", "ta-1@example.com", cognito)).isValid, false);
    assert.equal((await validateAdminOperation(["TA_t1"], "GET", "", cognito)).isValid, false);
  });

  test("paginated target groups: SA on the second page is seen and denies TA_t1 (codex W2 round 1)", async () => {
    const paged = {
      async send(cmd) {
        assert.ok(cmd instanceof AdminListGroupsForUserCommand);
        if (!cmd.input.NextToken) return { Groups: [{ GroupName: "TA_t1" }], NextToken: "page2" };
        return { Groups: [{ GroupName: "SA" }] };
      },
    };
    assert.equal((await validateAdminOperation(["TA_t1"], "DELETE", "paged@example.com", paged)).isValid, false);
  });
});
